/* * @lc app=leetcode id=1302 lang=kotlin * * [1302] Deepest Leaves Sum */ class Solution { fun deepestLeavesSum(root: TreeNode?): Int = root?.let { java.util.ArrayDeque<TreeNode>().apply { add(it) }.let { q -> generateSequence { q.takeIf { it.isNotEmpty() } } .map { (0 until q.size).sumOf { q.poll().let { node -> node.left?.let { q.add(it) } node.right?.let { q.add(it) } node.`val` } } } .last() } } ?: 0 }